#include <QApplication>

#include "LabCheck.h"
#include "MainWindow.h"

// CSCI 1260 GUIs and Events Lab. Do not edit this file.
//
//   ./build/gui_events_lab          opens the window
//   ./build/gui_events_lab check    prints the lab check instead
//
// On GitHub there is no screen, so the check runs on its own there.

// Runs the check when asked. Otherwise opens the window until it is closed.
int main(int argc, char* argv[])
{
    bool check = LabCheck::ShouldRun(argc, argv);
    if (check)
    {
        // The check needs no screen, so Qt draws the windows in memory.
        // This must happen before the QApplication is created.
        qputenv("QT_QPA_PLATFORM", "offscreen");
    }
    QApplication app(argc, argv);

    int exitCode = 0;
    if (check)
    {
        LabCheck::Run();
    }
    else
    {
        MainWindow window;
        window.show();
        exitCode = app.exec();
    }
    return exitCode;
}
